using Scheduling.Legacy;

namespace Scheduling;

/// <summary>Builds an exportable calendar feed for a resource.</summary>
public sealed class CalendarFeed
{
    public string Build(Resource resource)
    {
        var events = new List<string>();
        foreach (var slot in resource.Calendar)
            events.Add($"{resource.Name}:{slot.Start:O}-{slot.End:O}");
        return FeedApiV2.Serialize(events);
    }
}
